import assert from "node:assert/strict";
import { mkdtemp, mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";

import * as pybotModule from "../index.js";
import { clip, parseArgs, runPython, statusHint } from "../index.js";
globalThis.__pybotModule = pybotModule;

async function withHome(fn) {
	const home = await mkdtemp(join(tmpdir(), "dsh-python-"));
	const previous = process.env.DSH_HOME;
	process.env.DSH_HOME = home;
	try {
		return await fn(home);
	} finally {
		if (previous === undefined) delete process.env.DSH_HOME;
		else process.env.DSH_HOME = previous;
	}
}

/** Watch req/ and answer like the ArkTS bridge would. */
function startFakeRuntime(home, build) {
	const reqDir = join(home, "python", "req");
	const resDir = join(home, "python", "res");
	let timer;
	const ready = (async () => {
		await mkdir(reqDir, { recursive: true });
		await mkdir(resDir, { recursive: true });
		timer = setInterval(async () => {
			let names = [];
			try {
				const { readdir } = await import("node:fs/promises");
				names = await readdir(reqDir);
			} catch (_) {
				return;
			}
			for (const name of names) {
				if (!name.startsWith("req-") || !name.endsWith(".json")) continue;
				const request = JSON.parse(await readFile(join(reqDir, name), "utf8"));
				const result = build(request);
				await writeFile(join(resDir, `res-${request.id}.json`), JSON.stringify(result), "utf8");
				// Consume the request so the next tick cannot answer it twice and
				// race the plugin's own cleanup (flaky "ok:false" assertion).
				await unlink(join(reqDir, name)).catch(() => {});
			}
		}, 20);
	})();
	return {
		ready,
		stop() {
			clearInterval(timer);
		}
	};
}

test("parseArgs requires code and clamps the timeout", () => {
	assert.throws(() => parseArgs({}), /code is required/);
	assert.throws(() => parseArgs({ code: "  " }), /code is required/);
	const parsed = parseArgs({ code: "print(1)" });
	assert.equal(parsed.code, "print(1)");
	assert.equal(parsed.timeoutMs, 90000);
	assert.equal(parseArgs({ code: "x", timeout_ms: 5 }).timeoutMs, 1000);
	assert.equal(parseArgs({ code: "x", timeout_ms: 999999 }).timeoutMs, 300000);
	assert.throws(() => parseArgs({ code: "x".repeat(200001) }), /too long/);
});

test("clip marks how much was dropped", () => {
	assert.equal(clip("abc", 5), "abc");
	const clipped = clip("abcdef", 3);
	assert.match(clipped, /^abc\n/);
	assert.match(clipped, /已截断 3 字符/);
});

test("statusHint prefers a load error over a version", () => {
	assert.equal(statusHint(undefined), "");
	assert.match(statusHint({ ok: false, error: "wasm blocked" }), /wasm blocked/);
	assert.match(statusHint({ ok: true, version: "3.13.0 (main)" }), /3\.13\.0/);
});

test("runPython writes a request and returns the bridge result", async () => {
	await withHome(async (home) => {
		const fake = startFakeRuntime(home, (request) => ({
			ok: true,
			stdout: "hello\n",
			stderr: "",
			value: String(request.code.length)
		}));
		await fake.ready;
		try {
			const result = await runPython("print('hello')", { timeoutMs: 2000 });
			assert.equal(result.ok, true);
			assert.equal(result.stdout, "hello\n");
			assert.equal(result.value, "14");
			assert.ok(result.durationMs >= 0);
		} finally {
			fake.stop();
		}
	});
});

test("runPython surfaces a Python exception as ok:false", async () => {
	await withHome(async (home) => {
		const fake = startFakeRuntime(home, () => ({
			ok: false,
			stdout: "",
			stderr: "Traceback: boom\n",
			error: "boom"
		}));
		await fake.ready;
		try {
			const result = await runPython("raise ValueError('boom')", { timeoutMs: 2000 });
			assert.equal(result.ok, false);
			assert.match(result.stderr, /boom/);
			assert.equal(result.error, "boom");
		} finally {
			fake.stop();
		}
	});
});

test("a missing bridge times out and includes the runtime status", async () => {
	await withHome(async (home) => {
		await mkdir(join(home, "python"), { recursive: true });
		await writeFile(join(home, "python", "status.json"), JSON.stringify({
			ok: false,
			version: "",
			error: "WebAssembly blocked"
		}), "utf8");
		await assert.rejects(
			runPython("print(1)", { timeoutMs: 1000 }),
			(error) => error.code === "PYTHON_TIMEOUT" && /WebAssembly blocked/.test(error.message)
		);
	});
});

test("readInputFiles fences paths and returns base64", async () => {
	const { readInputFiles } = await import("../index.js");
	const ctx = {
		workingDirectory: { ensure: async () => "/workspace" },
		fs: {
			resolve: async (path) => ({ path }),
			contains: () => true,
			stat: async () => ({ type: "file", size: 5 }),
			readBytes: async () => Buffer.from("a,b\n1")
		}
	};
	const files = await readInputFiles(ctx, { agent: {}, signal: undefined }, ["data.csv"]);
	assert.equal(files.length, 1);
	assert.equal(files[0].name, "data.csv");
	assert.equal(Buffer.from(files[0].data, "base64").toString("utf8"), "a,b\n1");
});

test("parseArgs accepts files and rejects non-arrays", () => {
	assert.deepEqual(parseArgs({ code: "x", files: ["a.csv"] }).files, ["a.csv"]);
	assert.deepEqual(parseArgs({ code: "x" }).packages, ["pandas"]);
	assert.deepEqual(parseArgs({ code: "x", packages: [] }).packages, []);
	assert.throws(() => parseArgs({ code: "x", packages: "pandas" }), /packages must be an array/);
	assert.throws(() => parseArgs({ code: "x", files: "a.csv" }), /files must be an array/);
});

test("buildPybotCode keeps model text out of the Python source", () => {
	const { buildPybotCode } = requirePybot();
	const code = buildPybotCode("hello'); import os; os.system('x", "t1", true);
	assert.match(code, /base64\.b64decode/);
	assert.ok(!code.includes("os.system('x"));
	assert.match(code, /if True or thread not in states/);
});

test("parsePybotOutput tolerates module debug lines", () => {
	const { parsePybotOutput } = requirePybot();
	const parsed = parsePybotOutput('debug line\n__PYBOT__{"reply":"hi","module":"greet","seconds":0.2}\n');
	assert.equal(parsed.reply, "hi");
	assert.equal(parsed.module, "greet");
	assert.equal(parsed.seconds, 0.2);
	assert.throws(() => parsePybotOutput("no marker"), /no reply marker/);
});

test("parsePybotArgs defaults, clamps and validates", () => {
	const { parsePybotArgs } = requirePybot();
	const parsed = parsePybotArgs({ text: "hello" });
	assert.equal(parsed.thread, "default");
	assert.equal(parsed.reset, false);
	assert.equal(parsed.timeoutMs, 120000);
	assert.equal(parsePybotArgs({ text: "x", thread: " a ", reset: true, timeout_ms: 5 }).timeoutMs, 1000);
	assert.throws(() => parsePybotArgs({}), /text is required/);
	assert.throws(() => parsePybotArgs({ text: "x".repeat(20001) }), /too long/);
});

test("runPybot parses the bridge marker", async () => {
	const { runPybot } = requirePybot();
	await withHome(async (home) => {
		const fake = startFakeRuntime(home, () => ({
			ok: true,
			stdout: '__PYBOT__{"reply":"That is 4.","module":"math","seconds":0.01}\n',
			stderr: "",
			value: ""
		}));
		await fake.ready;
		try {
			const result = await runPybot("what is 2+2?", { timeoutMs: 2000 });
			assert.equal(result.reply, "That is 4.");
			assert.equal(result.module, "math");
		} finally {
			fake.stop();
		}
	});
});

function requirePybot() {
	return globalThis.__pybotModule;
}
